1	/**
2	 * @module @sentinelflow/interceptors/identity
3	 *
4	 * Identity and delegation governance — links agent actions to human sponsors.
5	 *
6	 * This module answers the question compliance auditors always ask:
7	 * "Who authorized this agent to run, and what is it allowed to do?"
8	 *
9	 * Three components:
10	 *
11	 *   1. IdentityResolver — populates identity context on every event
12	 *      from policy config, environment variables, and git config.
13	 *
14	 *   2. RoleBasedAccessPolicy — enforces "low-privilege agents may not
15	 *      call high-privilege tools" using the agent's role/privilege level.
16	 *
17	 *   3. EnvironmentPolicy — enforces environment-specific restrictions
18	 *      like "production agents cannot use write tools" or "external-facing
19	 *      agents cannot touch restricted paths."
20	 *
21	 * Maps to:
22	 *   - OWASP LLM09 (Excessive Agency): prevents agents from exceeding authorized scope
23	 *   - OWASP LLM08 (Insecure Plugin Design): controls which tools each agent can use
24	 *   - EU AI Act Article 14: human oversight and intervention capability
25	 *   - NIST AI RMF Govern 1.4: organizational roles and responsibilities
26	 *   - SOC 2 CC6.1: logical and physical access controls
27	 */
28	
29	import type {
30	  AgentEvent,
31	  IdentityContext,
32	  AgentRole,
33	  Environment,
34	} from "@sentinelflow/core";
35	import type { PolicyProvider, PolicyEvaluationResult, EventListener } from "./interface";
36	import { SHELL_TOOL_NAMES } from "./patterns";
37	
38	// ─── Role → Privilege Level Mapping ─────────────────────────────────
39	
40	const DEFAULT_ROLE_PRIVILEGES: Record<AgentRole, number> = {
41	  reader: 2,
42	  writer: 4,
43	  executor: 6,
44	  deployer: 8,
45	  admin: 10,
46	  custom: 5,
47	};
48	
49	// ─── Tool → Minimum Privilege Mapping ───────────────────────────────
50	
51	/**
52	 * Default tool privilege requirements.
53	 * Tools not listed here require privilege level 1 (anyone can use them).
54	 */
55	const DEFAULT_TOOL_PRIVILEGES: Record<string, number> = {
56	  // Shell tools require executor (6) or higher
57	  Bash: 6, bash: 6, shell: 6, Shell: 6,
58	  terminal: 6, Terminal: 6, exec: 6, Exec: 6,
59	  RunCommand: 6, run_command: 6, execute: 6, Execute: 6,
60	
61	  // Write tools require writer (4) or higher
62	  Write: 4, write: 4, Edit: 4, edit: 4,
63	  MultiEdit: 4, multiedit: 4, Create: 4, create: 4,
64	  FileEdit: 4, file_edit: 4, create_file: 4, write_file: 4,
65	
66	  // Deploy tools require deployer (8) or higher
67	  NotebookEdit: 8, TodoWrite: 8,
68	};
69	
70	// ─── 1. Identity Resolver ───────────────────────────────────────────
71	
72	export interface IdentityConfig {
73	  /** Human owner of this agent (required for audit compliance) */
74	  human_owner?: string;
75	  /** Owner email */
76	  human_email?: string;
77	  /** Team name */
78	  team?: string;
79	  /** Deployment environment */
80	  environment?: Environment;
81	  /** Agent role */
82	  role?: AgentRole;
83	  /** Privilege level (overrides role-based default) */
84	  privilege_level?: number;
85	  /** Whether agent faces external users */
86	  external_facing?: boolean;
87	  /** Custom tags */
88	  tags?: string[];
89	  /** Per-agent role overrides: agent_id → role */
90	  agent_roles?: Record<string, AgentRole>;
91	  /** Per-agent privilege overrides: agent_id → level */
92	  agent_privileges?: Record<string, number>;
93	}
94	
95	/**
96	 * Resolves identity context for every event.
97	 *
98	 * Acts as an EventListener — attaches identity to each event as it flows
99	 * through the pipeline. Downstream policies can then use event.identity
100	 * to make access control decisions.
101	 *
102	 * Resolution order:
103	 *   1. Per-agent overrides (agent_roles, agent_privileges)
104	 *   2. Explicit config (role, privilege_level, human_owner)
105	 *   3. Environment variables (SENTINELFLOW_OWNER, SENTINELFLOW_TEAM, etc.)
106	 *   4. Defaults (role: executor, environment: development, privilege: 6)
107	 */
108	export class IdentityResolver implements EventListener {
109	  readonly name = "identity_resolver";
110	
111	  private _config: IdentityConfig;
112	  private _defaultIdentity: IdentityContext;
113	
114	  constructor(config?: IdentityConfig) {
115	    this._config = config ?? {};
116	
117	    // Resolve the default identity from config + environment
118	    const role = this._config.role ?? this.envOr("SENTINELFLOW_ROLE", "executor") as AgentRole;
119	    const privLevel = this._config.privilege_level ?? DEFAULT_ROLE_PRIVILEGES[role] ?? 5;
120	
121	    this._defaultIdentity = {
122	      human_owner:
123	        this._config.human_owner ??
124	        this.envOr("SENTINELFLOW_OWNER", undefined) ??
125	        this.envOr("USER", undefined) ??
126	        this.envOr("GITHUB_ACTOR", "unknown"),
127	      human_email:
128	        this._config.human_email ??
129	        this.envOr("SENTINELFLOW_EMAIL", undefined),
130	      team:
131	        this._config.team ??
132	        this.envOr("SENTINELFLOW_TEAM", undefined) ??
133	        this.envOr("GITHUB_REPOSITORY_OWNER", undefined),
134	      environment: this._config.environment ?? this.resolveEnvironment(),
135	      role,
136	      privilege_level: privLevel,
137	      external_facing: this._config.external_facing ?? false,
138	      tags: this._config.tags ?? [],
139	    };
140	  }
141	
142	  /** Attach identity context to every event */
143	  onEvent(event: AgentEvent): void {
144	    if (!event.identity) {
145	      event.identity = this.resolveForAgent(event.agent_id);
146	    }
147	  }
148	
149	  /** Get the identity context for a specific agent */
150	  resolveForAgent(agentId: string): IdentityContext {
151	    const agentRole = this._config.agent_roles?.[agentId];
152	    const agentPriv = this._config.agent_privileges?.[agentId];
153	
154	    if (!agentRole && agentPriv === undefined) {
155	      return { ...this._defaultIdentity };
156	    }
157	
158	    const role = agentRole ?? this._defaultIdentity.role;
159	    return {
160	      ...this._defaultIdentity,
161	      role,
162	      privilege_level: agentPriv ?? DEFAULT_ROLE_PRIVILEGES[role] ?? this._defaultIdentity.privilege_level,
163	    };
164	  }
165	
166	  /** Get the default identity (for display/debug) */
167	  getDefaultIdentity(): IdentityContext {
168	    return { ...this._defaultIdentity };
169	  }
170	
171	  private envOr(key: string, fallback: string | undefined): string | undefined {
172	    try {
173	      return process.env[key] ?? fallback;
174	    } catch {
175	      return fallback;
176	    }
177	  }
178	
179	  private resolveEnvironment(): Environment {
180	    // Check common CI/CD environment indicators
181	    const ciVars = ["CI", "GITHUB_ACTIONS", "GITLAB_CI", "JENKINS_URL", "CIRCLECI", "BUILDKITE"];
182	    for (const v of ciVars) {
183	      try { if (process.env[v]) return "ci"; } catch { /* ignore */ }
184	    }
185	
186	    // Check explicit env var
187	    const envStr = this.envOr("SENTINELFLOW_ENV", undefined)?.toLowerCase();
188	    if (envStr === "production" || envStr === "prod") return "production";
189	    if (envStr === "staging" || envStr === "stage") return "staging";
190	    if (envStr === "development" || envStr === "dev") return "development";
191	    if (envStr === "ci") return "ci";
192	
193	    // Check NODE_ENV
194	    const nodeEnv = this.envOr("NODE_ENV", undefined)?.toLowerCase();
195	    if (nodeEnv === "production") return "production";
196	    if (nodeEnv === "staging") return "staging";
197	
198	    return "development";
199	  }
200	}
201	
202	// ─── 2. Role-Based Access Policy ────────────────────────────────────
203	
204	/**
205	 * Enforces role-based access control for agent tool calls.
206	 *
207	 * "Low-privilege agents may not call high-privilege tools."
208	 *
209	 * Uses the identity context attached to events by IdentityResolver.
210	 * If no identity is present, uses a configurable default privilege level.
211	 *
212	 * Maps to:
213	 *   - OWASP LLM09: Excessive Agency
214	 *   - SOC 2 CC6.1: Logical Access Controls
215	 *   - NIST AI RMF Map 1.5: AI-specific access management
216	 */
217	export class RoleBasedAccessPolicy implements PolicyProvider {
218	  readonly name = "role_based_access";
219	
220	  private _toolPrivileges: Record<string, number>;
221	  private _defaultAgentPrivilege: number;
222	
223	  constructor(config?: {
224	    /** Override default tool → privilege mappings */
225	    toolPrivileges?: Record<string, number>;
226	    /** Default privilege for agents without identity context */
227	    defaultAgentPrivilege?: number;
228	  }) {
229	    this._toolPrivileges = {
230	      ...DEFAULT_TOOL_PRIVILEGES,
231	      ...(config?.toolPrivileges ?? {}),
232	    };
233	    this._defaultAgentPrivilege = config?.defaultAgentPrivilege ?? 6;
234	  }
235	
236	  evaluate(event: AgentEvent): PolicyEvaluationResult {
237	    const start = Date.now();
238	    const toolName = event.tool?.name;
239	    if (!toolName) {
240	      return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
241	    }
242	
243	    // Get required privilege for this tool
244	    const requiredPrivilege = this._toolPrivileges[toolName] ?? 1;
245	
246	    // Get agent's privilege level from identity context
247	    const agentPrivilege = event.identity?.privilege_level ?? this._defaultAgentPrivilege;
248	    const agentRole = event.identity?.role ?? "unknown";
249	    const agentOwner = event.identity?.human_owner ?? "unknown";
250	
251	    if (agentPrivilege < requiredPrivilege) {
252	      return {
253	        decision: "block",
254	        matched_policies: [this.name],
255	        reason:
256	          `Agent "${event.agent_id}" (role: ${agentRole}, privilege: ${agentPrivilege}, ` +
257	          `owner: ${agentOwner}) attempted to use tool "${toolName}" ` +
258	          `which requires privilege level ${requiredPrivilege}. ` +
259	          `Increase agent privilege or assign a higher role.`,
260	        evaluation_ms: Date.now() - start,
261	      };
262	    }
263	
264	    return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
265	  }
266	}
267	
268	// ─── 3. Environment Policy ──────────────────────────────────────────
269	
270	/**
271	 * Enforces environment-specific restrictions.
272	 *
273	 * Examples:
274	 *   - "Production agents cannot use Bash or Write tools"
275	 *   - "External-facing agents cannot access restricted paths"
276	 *   - "CI agents can only use read and test tools"
277	 *
278	 * Maps to:
279	 *   - EU AI Act Article 9: Risk management across environments
280	 *   - SOC 2 CC8.1: Change management (production restrictions)
281	 *   - NIST AI RMF Govern 1.7: AI deployment governance
282	 */
283	export class EnvironmentPolicy implements PolicyProvider {
284	  readonly name = "environment_policy";
285	
286	  private _productionBlockedTools: Set<string>;
287	  private _ciAllowedTools: Set<string>;
288	  private _externalBlockedTools: Set<string>;
289	  private _stagingBlockedTools: Set<string>;
290	
291	  constructor(config?: {
292	    /** Tools blocked in production. Default: all shell + write tools */
293	    productionBlockedTools?: string[];
294	    /** Tools allowed in CI. Default: read + test tools only */
295	    ciAllowedTools?: string[];
296	    /** Tools blocked for external-facing agents. Default: shell + write tools */
297	    externalBlockedTools?: string[];
298	    /** Tools blocked in staging. Default: deploy tools */
299	    stagingBlockedTools?: string[];
300	  }) {
301	    this._productionBlockedTools = new Set(
302	      config?.productionBlockedTools ?? [...SHELL_TOOL_NAMES]
303	    );
304	    this._ciAllowedTools = new Set(
305	      config?.ciAllowedTools ?? [
306	        "Read", "read", "ReadFile", "read_file",
307	        "ListDir", "list_dir", "View", "view",
308	        "Bash", "bash", // CI needs bash for test/build
309	      ]
310	    );
311	    this._externalBlockedTools = new Set(
312	      config?.externalBlockedTools ?? [
313	        ...SHELL_TOOL_NAMES,
314	        "Write", "write", "Edit", "edit", "MultiEdit", "multiedit",
315	        "Create", "create",
316	      ]
317	    );
318	    this._stagingBlockedTools = new Set(
319	      config?.stagingBlockedTools ?? ["NotebookEdit", "TodoWrite"]
320	    );
321	  }
322	
323	  evaluate(event: AgentEvent): PolicyEvaluationResult {
324	    const start = Date.now();
325	    const toolName = event.tool?.name;
326	    if (!toolName) {
327	      return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
328	    }
329	
330	    const env = event.identity?.environment ?? "development";
331	    const isExternal = event.identity?.external_facing ?? false;
332	    const owner = event.identity?.human_owner ?? "unknown";
333	
334	    // Production restrictions
335	    if (env === "production" && this._productionBlockedTools.has(toolName)) {
336	      return {
337	        decision: "block",
338	        matched_policies: [this.name],
339	        reason:
340	          `Tool "${toolName}" is blocked in production environment. ` +
341	          `Agent "${event.agent_id}" (owner: ${owner}) attempted a restricted operation. ` +
342	          `Production agents should use read-only tools or request a deployment pipeline.`,
343	        evaluation_ms: Date.now() - start,
344	      };
345	    }
346	
347	    // CI restrictions (allowlist-based)
348	    if (env === "ci" && !this._ciAllowedTools.has(toolName)) {
349	      return {
350	        decision: "block",
351	        matched_policies: [this.name],
352	        reason:
353	          `Tool "${toolName}" is not in the CI-allowed tools list. ` +
354	          `CI agents can only use: ${[...this._ciAllowedTools].join(", ")}.`,
355	        evaluation_ms: Date.now() - start,
356	      };
357	    }
358	
359	    // External-facing agent restrictions
360	    if (isExternal && this._externalBlockedTools.has(toolName)) {
361	      return {
362	        decision: "block",
363	        matched_policies: [this.name],
364	        reason:
365	          `Tool "${toolName}" is blocked for external-facing agents. ` +
366	          `Agent "${event.agent_id}" is marked as external_facing and cannot ` +
367	          `use write or execute tools. Restrict to read-only operations.`,
368	        evaluation_ms: Date.now() - start,
369	      };
370	    }
371	
372	    // Staging restrictions
373	    if (env === "staging" && this._stagingBlockedTools.has(toolName)) {
374	      return {
375	        decision: "block",
376	        matched_policies: [this.name],
377	        reason:
378	          `Tool "${toolName}" is blocked in staging environment.`,
379	        evaluation_ms: Date.now() - start,
380	      };
381	    }
382	
383	    return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
384	  }
385	}
