232	  readonly name = "enhanced_data_boundary";
233	
234	  private _classifier: PathClassifier;
235	  private _agentClearances: Map<string, DataClassification>;
236	  private _defaultMaxClassification: DataClassification;
237	  private _wildcardClearances: Array<{ pattern: RegExp; max: DataClassification }>;
238	
239	  constructor(config?: {
240	    /** Custom classification rules (replaces defaults) */
241	    classificationRules?: ClassificationRule[];
242	    /** Per-agent clearance levels */
243	    agentClearances?: AgentClearance[];
244	    /** Default max classification for unlisted agents. Default: "internal" */
245	    defaultMaxClassification?: DataClassification;
246	  }) {
247	    this._classifier = new PathClassifier(config?.classificationRules);
248	    this._defaultMaxClassification = config?.defaultMaxClassification ?? "internal";
249	
250	    this._agentClearances = new Map();
251	    this._wildcardClearances = [];
252	
253	    for (const c of config?.agentClearances ?? []) {
254	      if (c.agent.includes("*")) {
255	        const pattern = new RegExp("^" + c.agent.replace(/\*/g, ".*") + "$");
256	        this._wildcardClearances.push({ pattern, max: c.maxClassification });
257	      } else {
258	        this._agentClearances.set(c.agent, c.maxClassification);
259	      }
260	    }
261	  }
262	
263	  private getAgentMaxClassification(agentId: string): DataClassification {
264	    // Exact match first
265	    const exact = this._agentClearances.get(agentId);
266	    if (exact) return exact;
267	
268	    // Wildcard match
269	    for (const { pattern, max } of this._wildcardClearances) {
270	      if (pattern.test(agentId)) return max;
271	    }
272	
273	    return this._defaultMaxClassification;
274	  }
275	
276	  evaluate(event: AgentEvent): PolicyEvaluationResult {
277	    const start = Date.now();
278	
279	    // Extract all paths from the event
280	    const paths = extractPaths(event);
281	    if (paths.length === 0) {
282	      return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
283	    }
284	
285	    // Get the highest classification among all paths
286	    const highest = this._classifier.classifyHighest(paths);
287	    if (!highest) {
288	      return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
289	    }
290	
291	    // Check against agent clearance
292	    const agentMax = this.getAgentMaxClassification(event.agent_id);
293	    const agentLevel = CLASSIFICATION_LEVEL[agentMax];
294	    const pathLevel = CLASSIFICATION_LEVEL[highest.classification];
295	
296	    if (pathLevel > agentLevel) {
297	      return {
298	        decision: "block",
299	        matched_policies: [this.name],
300	        reason: `Agent "${event.agent_id}" (clearance: ${agentMax}) attempted to access ` +
301	          `${highest.classification}-level path "${highest.path}" (${highest.label}). ` +
302	          `Requires ${highest.classification} clearance or higher.`,
303	        evaluation_ms: Date.now() - start,
304	      };
305	    }
306	
307	    return { decision: "allow", matched_policies: [], evaluation_ms: Date.now() - start };
308	  }
309	}
