81	  L(`function _sfStripQuotes(s) {`);
82	  L(`  if (!s) return "";`);
83	  L(`  var t = String(s);`);
84	  L(`  if ((t[0] === '"' && t[t.length - 1] === '"') || (t[0] === "'" && t[t.length - 1] === "'")) {`);
