95	  L(`  var seenTee = false;`);
96	  L(`  for (var i = 0; i < tokens.length; i++) {`);
97	  L(`    var tok = tokens[i];`);
98	  L(`    if (!tok) continue;`);
99	  L(``);
100	  L(`    // tee writes to files (e.g. tee -a ~/.ssh/authorized_keys)`);
101	  L(`    if (tok === "tee") { seenTee = true; continue; }`);
102	  L(`    if (seenTee) {`);
103	  L(`      if (tok[0] === "-") continue;`);
104	  L(`      out.push(_sfStripQuotes(tok));`);
105	  L(`      // keep scanning: tee can take multiple file operands`);
106	  L(`      continue;`);
107	  L(`    }`);
