116	  L(`    if (gt !== -1 && gt + 1 < tok.length) {`);
117	  L(`      var tail = tok.slice(gt + 1);`);
118	  L(`      // ignore cases like "->" or "=>" by requiring a plausible path start`);
119	  L(`      if (tail[0] === "/" || tail[0] === "." || tail[0] === "~") out.push(_sfStripQuotes(tail));`);
