150	  L(`function _sfExtractDomain(s) {`);
151	  L(`  if (!s) return "";`);
152	  L(`  var t = _sfStripQuotes(String(s));`);
153	  L(`  var at = t.lastIndexOf("@");`);
154	  L(`  if (at !== -1 && at + 1 < t.length) t = t.slice(at + 1);`);
