162	  L(`  t = t.toLowerCase().replace(/[^a-z0-9._-]/g, "");`);
163	  L(`  return t;`);
164	  L(`}`);
165	  L(``);
166	
167	  L(`function _sfIsDomainAllowed(domain) {`);
168	  L(`  if (!domain) return true;`);
169	  L(`  var allowed = Array.isArray(EGRESS_ALLOWED_DOMAINS) ? EGRESS_ALLOWED_DOMAINS : [];`);
170	  L(`  var blocked = Array.isArray(EGRESS_BLOCKED_DOMAINS) ? EGRESS_BLOCKED_DOMAINS : [];`);
171	  L(`  var blockedSet = new Set(blocked.map(function(d){ return String(d || "").toLowerCase(); }));`);
172	  L(`  if (blockedSet.has(domain)) return false;`);
173	  L(`  var allowExact = new Set();`);
174	  L(`  var allowWild = [];`);
175	  L(`  for (var i = 0; i < allowed.length; i++) {`);
176	  L(`    var d = String(allowed[i] || "").toLowerCase();`);
177	  L(`    if (!d) continue;`);
