190	  L(`var _sfSensitivePaths = ${sensitivePaths}.map(function(p) {`);
191	  L(`  try { return { id: p.id, re: new RegExp(p.regex, "i"), label: p.label }; }`);
192	  L(`  catch(e) { return null; }`);
193	  L(`}).filter(Boolean);`);
