195	  L(`var WRITE_TOOLS = new Set(["Write","write","Edit","edit","MultiEdit","multiedit","Create","create","FileEdit","file_edit","create_file","write_file","edit_file","NotebookEdit","TodoWrite"]);`);
196	  L(``);
197	
198	  L(`// --- Enterprise Policy Evaluation ---`);
199	  L(`function evaluatePolicy(toolName, toolInput) {`);
200	  L(`  if (TOOL_BLOCKLIST.has(toolName))`);
201	  L(`    return { block: true, flag: true, reason: "Tool \\"" + toolName + "\\" is in the blocklist", id: "tool_blocklist" };`);
202	  L(`  // Tool allowlist semantics: if allowlist is configured, deny everything not explicitly allowed.`);
203	  L(`  // In monitor mode we do not block, but we still return a reason/id for logging parity.`);
204	  L(`  if (TOOL_ALLOWLIST.size > 0 && !TOOL_ALLOWLIST.has(toolName)) {`);
205	  L(`    var enforce = ENFORCEMENT_MODE === "enforce";`);
206	  L(`    return { block: enforce, flag: true, reason: "Tool \\"" + toolName + "\\" is not in the allowlist", id: "tool_allowlist" };`);
207	  L(`  }`);
208	  L(`  if (TOOL_ALLOWLIST.size > 0 && TOOL_ALLOWLIST.has(toolName))`);
209	  L(`    return { block: false, flag: false };`);
210	  L(``);
211	  L(`  var enforce = ENFORCEMENT_MODE === "enforce";`);
212	  L(`  var summary = _sfSummarize(toolInput);`);
213	  L(``);
214	  L(`  // Dangerous command detection (all shell tool variants)`);
215	  L(`  if (SHELL_TOOLS.has(toolName) && toolInput) {`);
216	  L(`    var rawCmd = "";`);
217	  L(`    if (typeof toolInput === "string") {`);
218	  L(`      try { rawCmd = JSON.parse(toolInput).command || ""; } catch(e) { rawCmd = toolInput; }`);
219	  L(`    } else { rawCmd = toolInput.command || ""; }`);
220	  L(``);
221	  L(`    if (rawCmd) {`);
222	  L(`      var cmdForDangerous = _sfNormalizeCommand(rawCmd);`);
223	  L(`      var cmdForSecrets = _sfNormalizeCommand(rawCmd);`);
224	  L(`      // Reduce obvious wrappers and absolute-path command forms for matching`);
225	  L(`      cmdForDangerous = cmdForDangerous.replace(/^(?:\\\\?command)\\s+/i, "");`);
226	  L(`      cmdForDangerous = cmdForDangerous.replace(/\\b\\/[\\w.+-]+(?:\\/[\\w.+-]+)+\\b/g, function(m){ return m.split('/').pop(); });`);
227	  L(`      for (var i = 0; i < _sfDangerous.length; i++) {`);
228	  L(`        if (_sfDangerous[i].re.test(cmdForDangerous)) {`);
229	  L(`          return { block: enforce, flag: true, reason: "Dangerous [" + _sfDangerous[i].id + "]: " + _sfDangerous[i].label + " -- " + rawCmd.slice(0, 100), id: "dangerous_commands" };`);
230	  L(`        }`);
231	  L(`      }`);
232	  L(``);
233	  L(`      // Secrets in shell commands`);
234	  L(`      for (var s = 0; s < _sfSecrets.length; s++) {`);
235	  L(`        if (_sfSecrets[s].re.test(cmdForSecrets)) {`);
236	  L(`          return { block: enforce, flag: true, reason: "Secret detected [" + _sfSecrets[s].id + "]: " + _sfSecrets[s].label, id: "secrets_leak" };`);
237	  L(`        }`);
238	  L(`      }`);
239	  L(``);
240	  L(`      // Network egress governance (domain allow/block lists)`);
241	  L(`      for (var ne = 0; ne < _sfNetworkEgress.length; ne++) {`);
242	  L(`        var m = cmdForSecrets.match(_sfNetworkEgress[ne].re);`);
243	  L(`        if (m) {`);
244	  L(`          var urlOrHost = m[_sfNetworkEgress[ne].urlGroupIndex] || m[0] || "";`);
245	  L(`          var domain = _sfExtractDomain(urlOrHost);`);
246	  L(`          if (domain && !_sfIsDomainAllowed(domain)) {`);
247	  L(`            return { block: enforce, flag: true, reason: "Network egress [" + _sfNetworkEgress[ne].id + "]: " + _sfNetworkEgress[ne].label + " — domain: " + domain, id: "network_egress" };`);
248	  L(`          }`);
249	  L(`        }`);
250	  L(`      }`);
251	  L(``);
252	  L(`      // Sensitive file write governance for shell redirections and tee`);
253	  L(`      var writeTargets = _sfExtractWriteTargets(cmdForSecrets);`);
254	  L(`      if (writeTargets && writeTargets.length) {`);
255	  L(`        for (var t = 0; t < writeTargets.length; t++) {`);
256	  L(`          var target = writeTargets[t];`);
257	  L(`          if (!target) continue;`);
258	  L(`          for (var wp = 0; wp < _sfSensitivePaths.length; wp++) {`);
259	  L(`            if (_sfSensitivePaths[wp].re.test(target)) {`);
260	  L(`              return { block: enforce, flag: true, reason: "Write to sensitive path [" + _sfSensitivePaths[wp].id + "]: " + _sfSensitivePaths[wp].label, id: "file_write" };`);
261	  L(`            }`);
262	  L(`          }`);
263	  L(`        }`);
264	  L(`      }`);
265	  L(`    }`);
266	  L(`  }`);
267	  L(``);
268	  L(`  // File write governance (Write/Edit tools)`);
269	  L(`  if (WRITE_TOOLS.has(toolName) && toolInput) {`);
270	  L(`    var fp = "";`);
271	  L(`    if (typeof toolInput === "string") {`);
272	  L(`      try { var pp = JSON.parse(toolInput); fp = pp.file_path || pp.filePath || pp.path || pp.file || ""; } catch(e) { fp = toolInput; }`);
273	  L(`    } else { fp = toolInput.file_path || toolInput.filePath || toolInput.path || toolInput.file || ""; }`);
274	  L(`    if (fp) {`);
275	  L(`      for (var w = 0; w < _sfSensitivePaths.length; w++) {`);
276	  L(`        if (_sfSensitivePaths[w].re.test(fp)) {`);
277	  L(`          return { block: enforce, flag: true, reason: "Write to sensitive path [" + _sfSensitivePaths[w].id + "]: " + _sfSensitivePaths[w].label, id: "file_write" };`);
278	  L(`        }`);
279	  L(`      }`);
280	  L(`    }`);
281	  L(`  }`);
282	  L(``);
283	  L(`  // Secrets in any tool input`);
284	  L(`  if (summary) {`);
285	  L(`    for (var k = 0; k < _sfSecrets.length; k++) {`);
286	  L(`      if (_sfSecrets[k].re.test(summary)) {`);
287	  L(`        return { block: enforce, flag: true, reason: "Secret detected [" + _sfSecrets[k].id + "]: " + _sfSecrets[k].label, id: "secrets_leak" };`);
288	  L(`      }`);
289	  L(`    }`);
290	  L(`  }`);
291	  L(``);
292	  L(`  return { block: false, flag: false };`);
293	  L(`}`);
294	
295	  return lines.join("\n");
296	}
