    id: p.id, regex: p.regex, label: p.description,
  })));

  const shellTools = JSON.stringify([...SHELL_TOOL_NAMES]);

  // Build the code as a plain string, NOT a template literal.
  // This avoids all escaping issues.
  const lines: string[] = [];
