214	        // On policy error, default to "flag" (fail-open in monitor, fail-closed in enforce)
215	        if (this._config.enforcement_mode === "enforce") {
216	          finalDecision = "block";
217	          blockReason = `Policy evaluation error: ${err}`;
218	        }
219	      }
220	    }
221	
222	    const evaluationMs = Date.now() - start;
223	    this._policyTotalMs += evaluationMs;
224	
225	    // In monitor mode, downgrade "block" to "flag" — never actually block
226	    if (this._config.enforcement_mode === "monitor" && finalDecision === "block") {
227	      this.log("warn", `Would block tool call (monitor mode): ${blockReason}`);
228	      finalDecision = "flag";
229	    }
230	
231	    return {
232	      decision: finalDecision,
233	      matched_policies: allMatched,
234	      reason: blockReason,
