250	
251	    // Fire-and-forget to all listeners (parallel, non-blocking)
252	    const promises = this._listeners.map(async (listener) => {
253	      try {
254	        await listener.onEvent(event);
255	      } catch (err) {
256	        this._errors++;
257	        this.log("error", `Listener ${listener.name} failed on ${event.type}: ${err}`);
258	      }
259	    });
260	
261	    await Promise.allSettled(promises);
262	  }
