264	  /**
265	   * The main tool-call interception flow. Framework interceptors call this
266	   * when they detect a tool call about to happen.
267	   *
268	   * Returns true if the tool call should proceed, false if blocked.
269	   */
270	  protected async handleToolCall(
271	    toolName: string,
272	    inputSummary?: string,
273	    metadata?: Record<string, unknown>
274	  ): Promise<{ allowed: boolean; event: AgentEvent }> {
275	    // 1. Create the pre-execution event
276	    const event = this.createEvent("tool_call_start", {
277	      tool: {
278	        name: toolName,
279	        input_summary: inputSummary,
280	        status: "success", // Will be updated if blocked
281	      },
282	      metadata,
283	    });
284	
285	    // 2. Run policy evaluation
286	    const policyResult = await this.evaluatePolicies(event);
287	
288	    // 3. Attach governance evaluation to the event
289	    event.governance = {
290	      policies_evaluated: this._policies.map((p) => p.name),
291	      policies_passed: policyResult.matched_policies.length === 0
292	        ? this._policies.map((p) => p.name)
293	        : this._policies
294	            .map((p) => p.name)
295	            .filter((n) => !policyResult.matched_policies.includes(n)),
296	      policies_failed: policyResult.matched_policies,
297	      action_taken: policyResult.decision === "block" ? "blocked" : "allowed",
298	      reason: policyResult.reason,
299	    };

