1	/**
2	 * Tests for HierarchicalEscalationPolicy and its coupling with
3	 * EnhancedDataBoundaryPolicy.
4	 *
5	 * Required scenarios (per session brief):
6	 *   1. In-scope → allow, no JSONL row
7	 *   2. Out-of-scope WITH supervisor → escalate, JSONL row written
8	 *   3. Out-of-scope WITHOUT supervisor → boundary blocks
9	 *   4. JSONL record carries all required fields including resolved_* nulls
10	 *   5. Reason string names supervisor + escalation_id
11	 *   6. Two out-of-scope calls → two unique escalation_ids
12	 *   7. Compose: both policies registered → only escalate wins,
13	 *      only one JSONL entry
14	 */
15	
16	import { afterEach, beforeEach, describe, expect, it } from "vitest";
17	import { existsSync, mkdtempSync, readFileSync, rmSync } from "fs";
18	import { tmpdir } from "os";
19	import { join } from "path";
20	
21	import type { AgentEvent, IdentityContext } from "@sentinelflow/core";
22	import { HierarchicalEscalationPolicy, type EscalationRecord } from "../escalation";
23	import { EnhancedDataBoundaryPolicy } from "../data-boundary";
24	
25	// ─── Test fixtures ──────────────────────────────────────────────────
26	
27	let tmpDir: string;
28	let logPath: string;
29	
30	beforeEach(() => {
31	  tmpDir = mkdtempSync(join(tmpdir(), "sf-escalation-"));
32	  logPath = join(tmpDir, ".sentinelflow", "escalations.jsonl");
33	});
34	
35	afterEach(() => {
36	  rmSync(tmpDir, { recursive: true, force: true });
37	});
38	
39	function makeIdentity(overrides: Partial<IdentityContext> = {}): IdentityContext {
40	  return {
41	    human_owner: "alice@example.com",
42	    environment: "development",
43	    role: "executor",
44	    privilege_level: 6,
45	    ...overrides,
46	  };
47	}
48	
49	function makeEvent(opts: {
50	  toolName?: string;
51	  inputSummary?: string;
52	  metadata?: Record<string, unknown>;
53	  identity?: IdentityContext;
54	  id?: string;
55	  session_id?: string;
56	  agent_id?: string;
57	} = {}): AgentEvent {
58	  return {
59	    id: opts.id ?? "evt_test_1",
60	    timestamp: new Date().toISOString(),
61	    agent_id: opts.agent_id ?? "claude-code-main",
62	    session_id: opts.session_id ?? "sess_test_1",
63	    type: "tool_call_start",
64	    tool: {
65	      name: opts.toolName ?? "Read",
66	      input_summary: opts.inputSummary,
67	      status: "success",
68	    },
69	    metadata: opts.metadata,
70	    identity: opts.identity,
71	  };
72	}
73	
74	function readJsonlLines(path: string): EscalationRecord[] {
75	  if (!existsSync(path)) return [];
76	  const raw = readFileSync(path, "utf8").trim();
77	  if (!raw) return [];
78	  return raw.split("\n").map((line) => JSON.parse(line) as EscalationRecord);
79	}
80	
81	// ─── 1. In-scope → allow ────────────────────────────────────────────
82	
83	describe("HierarchicalEscalationPolicy — in-scope access", () => {
84	  it("allows when path classification is within authorized_scope", () => {
85	    const policy = new HierarchicalEscalationPolicy({ logPath });
86	    const event = makeEvent({
87	      toolName: "Read",
88	      metadata: { file_path: "/Users/test/.aws/credentials" },
89	      identity: makeIdentity({
90	        authorized_scope: "restricted",
91	        supervisor: { id: "secops-admin", email: "secops@example.com" },
92	      }),
93	    });
94	
95	    const result = policy.evaluate(event);
96	
97	    expect(result.decision).toBe("allow");
98	    expect(result.matched_policies).toEqual([]);
99	    expect(existsSync(logPath)).toBe(false);
100	  });
101	});
102	
103	// ─── 2. Out-of-scope WITH supervisor → escalate + JSONL ─────────────
104	
105	describe("HierarchicalEscalationPolicy — escalation path", () => {
106	  it("escalates when path exceeds authorized_scope and writes a JSONL record", () => {
107	    const policy = new HierarchicalEscalationPolicy({ logPath });
108	    const event = makeEvent({
109	      toolName: "Read",
110	      metadata: { file_path: "/Users/test/.aws/credentials" },
111	      identity: makeIdentity({
112	        authorized_scope: "internal",
113	        supervisor: { id: "secops-admin", email: "secops@example.com" },
114	      }),
115	    });
116	
117	    const result = policy.evaluate(event);
118	
119	    expect(result.decision).toBe("escalate");
120	    expect(result.matched_policies).toEqual(["hierarchical_escalation"]);
121	
122	    const lines = readJsonlLines(logPath);
123	    expect(lines).toHaveLength(1);
124	    expect(lines[0]?.requested_classification).toBe("restricted");
125	    expect(lines[0]?.authorized_scope).toBe("internal");
126	  });
127	});
128	
129	// ─── 3. Out-of-scope WITHOUT supervisor → boundary blocks ───────────
130	
131	describe("HierarchicalEscalationPolicy — no supervisor configured", () => {
132	  it("escalation no-ops and EnhancedDataBoundaryPolicy emits a clear block", () => {
133	    const escalation = new HierarchicalEscalationPolicy({ logPath });
134	    const boundary = new EnhancedDataBoundaryPolicy({
135	      // Force the agent's clearance to "internal" so a restricted path blocks.
136	      agentClearances: [{ agent: "claude-code-main", maxClassification: "internal" }],
137	    });
138	
139	    const event = makeEvent({
140	      toolName: "Read",
141	      metadata: { file_path: "/Users/test/.aws/credentials" },
142	      identity: makeIdentity({
143	        authorized_scope: "internal",
144	        // supervisor intentionally omitted
145	      }),
146	    });
147	
148	    const escResult = escalation.evaluate(event);
149	    expect(escResult.decision).toBe("allow");
150	    expect(existsSync(logPath)).toBe(false);
151	
152	    const bndResult = boundary.evaluate(event);
153	    expect(bndResult.decision).toBe("block");
154	    expect(bndResult.reason).toMatch(/restricted/);
155	    expect(bndResult.reason).toMatch(/clearance/i);
156	  });
157	});
158	
159	// ─── 4. JSONL schema (incl. resolved_* nulls) ───────────────────────
160	
161	describe("HierarchicalEscalationPolicy — JSONL record schema", () => {
162	  it("writes all required fields including resolved_* nulls", () => {
163	    const policy = new HierarchicalEscalationPolicy({ logPath });
164	    const event = makeEvent({
165	      id: "evt_42",
166	      session_id: "sess_42",
167	      agent_id: "agent-42",
168	      toolName: "Read",
169	      metadata: { file_path: "/Users/test/.aws/credentials" },
170	      identity: makeIdentity({
171	        human_owner: "alice@example.com",
172	        authorized_scope: "internal",
173	        supervisor: { id: "secops-admin", email: "secops@example.com" },
174	      }),
175	    });
176	
177	    policy.evaluate(event);
178	
179	    const [record] = readJsonlLines(logPath);
180	    expect(record).toBeDefined();
181	    if (!record) return;
182	
183	    expect(record.schema_version).toBe(1);
184	    expect(record.escalation_id).toMatch(/^esc_\d+_[0-9a-f]{8}$/);
185	    expect(typeof record.timestamp).toBe("string");
186	    expect(new Date(record.timestamp).toString()).not.toBe("Invalid Date");
187	    expect(record.event_id).toBe("evt_42");
188	    expect(record.session_id).toBe("sess_42");
189	    expect(record.agent_id).toBe("agent-42");
190	    expect(record.human_owner).toBe("alice@example.com");
191	    expect(record.tool_name).toBe("Read");
192	    expect(record.requested_paths).toContain("/Users/test/.aws/credentials");
193	    expect(record.requested_classification).toBe("restricted");
194	    expect(record.requested_label).toMatch(/AWS credentials/i);
195	    expect(record.authorized_scope).toBe("internal");
196	    expect(record.supervisor).toEqual({ id: "secops-admin", email: "secops@example.com" });
197	    expect(record.status).toBe("pending");
198	    expect(record.resolved_at).toBeNull();
199	    expect(record.resolved_by).toBeNull();
200	    expect(record.resolution).toBeNull();
201	  });
202	
